mapper.update:
update orders
cancel_reason=#{cancelReason}, rejection_reason=#{rejectionReason}, cancel_time=#{cancelTime}, pay_status=#{payStatus}, pay_method=#{payMethod}, checkout_time=#{checkoutTime}, status = #{status}, delivery_time = #{deliveryTime}
where id = #{id}

mapper.select:
select id, number, status, user_id, address_book_id, order_time, checkout_time, pay_method, pay_status, amount, remark, phone, address, user_name, consignee, cancel_reason, rejection_reason, cancel_time, estimated_delivery_time, delivery_status, delivery_time, pack_amount, tableware_number, tableware_status
from orders

    and number like concat('%',#{number},'%')
    and phone like concat('%',#{phone},'%')
    and user_id = #{userId}
    and status = #{status}
    and order_time >= #{beginTime}
    and order_time <= #{endTime}

order by order_time desc

select count(*) from orders

    status = #{status}
    and order_time >= #{beginTime}
    and order_time <= #{endTime}

select od.name,sum(od.number) number from orders o,order_detail od
o.id = od.order_id and o.status = 5 and o.order_time >= #{beginTime} and o.order_time <= #{endTime}
group by od.name order by number desc limit 0,10
